def grade_score(score):
    if score < 0 or score > 100:
        return 'Invalid'
    if score >= 90:
        return 'A'
    if score >= 80:
        return 'B'
    return 'C'

partitions = [-5, 95, 85, 70, 105]
for score in partitions:
    print(f'score={score}: {grade_score(score)}')
